/**
 * "More ways to bring in words": a compact card for an account whose
 * notebooks are still small (owner, 2026-10-17).
 *
 * Most new learners type one word in the intro and onboarding, so they never
 * see the empty notebook, which is where importing and pasting were offered.
 * This card names the other ways in (a deck from another app, a list, the
 * extension and desktop shortcut, ChatGPT and Claude) until the notebook has
 * grown or the learner puts the card away. It sits below the day's plan on
 * Today and above the list in the notebook, never above the main card.
 */
import { Link } from 'react-router-dom';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { getMeta, setMeta } from '@/db/schema.js';
import { settingsPath } from '@/features/settings/paths.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { offersWaysIn } from './offer.js';
import styles from './WaysIn.module.css';

interface Way {
  id: string;
  icon: IconName;
  to: string;
  title: MessageKey;
  line: MessageKey;
}

/** The ways in, each to the screen that already does it. */
const WAYS: readonly Way[] = [
  {
    id: 'import',
    icon: 'notebook',
    to: settingsPath('data'),
    title: 'waysIn.importTitle',
    line: 'waysIn.importLine',
  },
  { id: 'list', icon: 'list', to: '/ai', title: 'waysIn.listTitle', line: 'waysIn.listLine' },
  {
    id: 'reading',
    icon: 'computer',
    to: settingsPath('everywhere'),
    title: 'waysIn.readingTitle',
    line: 'waysIn.readingLine',
  },
  {
    id: 'assistants',
    icon: 'sparkles',
    to: settingsPath('connected-apps'),
    title: 'waysIn.assistantsTitle',
    line: 'waysIn.assistantsLine',
  },
];

/** The card, or nothing once the notebook has grown or it was put away. */
export function WaysIn({ words }: { words: number }): React.JSX.Element | null {
  // Undefined until read, so a learner who put it away never sees it flash.
  const dismissed = useLiveQuery<boolean | undefined>(() => getMeta('waysInDismissed'), undefined, []);
  if (dismissed === undefined || !offersWaysIn(words, dismissed)) return null;
  return (
    <aside className={styles.card} aria-labelledby="ways-in-title">
      <div className={styles.head}>
        <h2 id="ways-in-title" className={styles.title}>
          {t('waysIn.title')}
        </h2>
        <button
          type="button"
          className={styles.close}
          aria-label={t('waysIn.hide')}
          onClick={() => {
            void setMeta('waysInDismissed', true);
          }}
        >
          <Icon name="close" size={16} weight={2} />
        </button>
      </div>
      <ul className={styles.list}>
        {WAYS.map((way) => (
          <li key={way.id}>
            <Link to={way.to} className={styles.row}>
              <span className={styles.icon} aria-hidden="true">
                <Icon name={way.icon} size={18} weight={1.9} />
              </span>
              <span className={styles.text}>
                <span className={styles.rowTitle}>{t(way.title)}</span>
                <span className={styles.line}>{t(way.line)}</span>
              </span>
              <Icon name="chevronRight" size={16} weight={2} className={styles.chevron} />
            </Link>
          </li>
        ))}
      </ul>
    </aside>
  );
}
