/**
 * A live query that starts from what this screen last read (`readMemory.ts`)
 * and says whether it has read anything yet.
 *
 * `useLiveQuery` starts every mount from a placeholder, which is right for a
 * small read and wrong for a screen whose placeholder looks like an answer:
 * an empty notebook's "Your words start here" is a claim about the data,
 * not a loading state. This hook keeps the two apart. `value` is undefined
 * only until the first read lands on a screen never drawn before in this
 * run; a screen drawn before gets its last read at once. `fresh` turns true
 * when this mount's own read has landed, for anything that must decide on
 * today's data rather than a moment-ago copy (a celebration, a once-only
 * line).
 */
import { liveQuery } from 'dexie';
import { useEffect, useState } from 'react';
import { recallRead, rememberRead } from './readMemory.js';

export interface RememberedRead<T> {
  /** The newest read, remembered or fresh; undefined until there is one. */
  value: T | undefined;
  /** Whether this mount's own read has landed. */
  fresh: boolean;
}

/**
 * Subscribes to a query whose result is remembered under `key`. `deps`
 * behaves like an effect's dependency list and must cover `key`. `scopeOf`
 * names the notebooks a result is of (`readScope`); a read that is not of
 * particular notebooks leaves it out.
 */
export function useRememberedQuery<T>(
  key: string,
  query: () => Promise<T>,
  deps: readonly unknown[],
  scopeOf?: (value: T) => string,
): RememberedRead<T> {
  const [state, setState] = useState<RememberedRead<T>>(() => ({
    value: recallRead(key) as T | undefined,
    fresh: false,
  }));

  useEffect(() => {
    let live = true;
    // Always an async querier: Dexie follows reads past a native `await`
    // only inside one, and every loader here awaits before it reads more.
    const subscription = liveQuery(async () => query()).subscribe({
      next: (next) => {
        if (!live) return;
        rememberRead(key, next, scopeOf?.(next));
        setState({ value: next, fresh: true });
      },
      error: (error: unknown) => {
        // A failed local read is a bug worth seeing, but it must not blank
        // the screen: the last good value stays on show.
        if (live) console.error('live query failed', error);
      },
    });
    return () => {
      live = false;
      subscription.unsubscribe();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  return state;
}
