/** When the "More ways to bring in words" card is offered (WaysIn.tsx). */

/**
 * Below this many words the card is offered. A product threshold about what
 * "still small" means for a notebook, not a limit or a tunable the server
 * owns: past it the learner has clearly found a way in that works for them.
 */
export const WAYS_IN_MAX_WORDS = 10;

/** Whether the card is for this many words. Pure, for the screens and tests. */
export function offersWaysIn(words: number, dismissed: boolean): boolean {
  return !dismissed && words < WAYS_IN_MAX_WORDS;
}
